insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The report does not claim that bilingual education solves every problem; it argues only that it can reduce one specific difficulty for adult learners, as described in a research summary.','According to the report, bilingual education is not a complete solution but may help with a particular problem.','The report argues that bilingual education solves all problems completely.','The report discusses many solutions but never mentions a specific problem.','The report rejects the idea that bilingual education can help in any way.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in public institutions, as described in a public debate.','The available data forced the researchers to reject all conclusions.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','The researchers postponed collecting data after reaching a firm conclusion.','The researchers made a recommendation because the data were complete.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes during periods of change, as described in a training program.','The author claims feedback is useful only when students stop practicing.','The author suggests that practice and feedback are unrelated.','The author believes practice works best if learners are told what they did wrong.','The author believes mistakes should be ignored during practice.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The new system was adopted not because it was cheaper, but because it made the process more transparent in small communities, as described in an evaluation report.','The new system was adopted mainly because it reduced costs.','The new system was rejected because it was not transparent.','The process became less transparent after the new system was adopted.','The main reason for adopting the new system was improved transparency rather than lower cost.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Even though the experiment was small, its results raised important questions for future research when resources are limited, as described in a committee meeting.','Despite its limited size, the experiment produced results that future studies should examine.','Future research became unnecessary after the experiment.','The results were ignored because the experiment was not small.','The experiment was too large to raise useful questions.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The passage implies that convenience may encourage people to use a service, but it does not guarantee satisfaction under careful supervision, as described in a student guide.','The passage denies that convenience affects service use.','The passage suggests that a convenient service can attract users without necessarily satisfying them.','The passage says convenience always guarantees satisfaction.','The passage argues that inconvenient services attract the most users.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The committee approved the plan only after several risks had been identified and addressed after initial trials, as described in a pilot study.','The plan was accepted although no risks were identified.','The committee approved the plan before considering any risks.','The plan was accepted once the committee had dealt with the risks it found.','The committee rejected the plan because all risks were addressed.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The decline in complaints was gradual, so managers were careful not to attribute it to a single change in schools, as described in a professional workshop.','Managers ignored the decline because it was caused by one change.','Managers blamed a single change because complaints rose quickly.','The decline in complaints was sudden and easy to explain.','Because complaints decreased slowly, managers avoided saying that one change alone caused the improvement.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',7,'The writer contrasts short-term popularity with long-term reliability for adult learners, as described in a policy review.','The writer points out a difference between being popular now and being dependable over time.','The writer discusses reliability without mentioning popularity.','The writer argues that long-term reliability is impossible.','The writer says popularity and reliability are exactly the same.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'C1','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Although peer feedback was initially criticized, later evidence showed that it could be useful when applied carefully in public institutions, as described in a classroom discussion.','Early criticism proved that peer feedback had no value at all.','Later evidence suggested that peer feedback, despite early criticism, may have value if used carefully.','The usefulness of peer feedback was accepted before anyone criticized it.','Later evidence showed that peer feedback should never be applied.','B','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The report does not claim that bilingual education solves every problem; it argues only that it can reduce one specific difficulty during periods of change, as described in a research summary.','The report argues that bilingual education solves all problems completely.','The report rejects the idea that bilingual education can help in any way.','According to the report, bilingual education is not a complete solution but may help with a particular problem.','The report discusses many solutions but never mentions a specific problem.','C','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'Researchers postponed their recommendation because the available data were too limited to support a firm conclusion in small communities, as described in a public debate.','The available data forced the researchers to reject all conclusions.','The researchers postponed collecting data after reaching a firm conclusion.','The researchers made a recommendation because the data were complete.','The researchers delayed giving advice since the evidence was insufficient for a definite conclusion.','D','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
insert into questions (type,difficulty,"questionText","choiceA","choiceB","choiceC","choiceD","correctAnswer","explanationHe",tags,"estimatedTimeSec","cefrLevel",status,"isPilot") values ('restatement',6,'The author suggests that frequent practice is effective only when learners receive feedback on their mistakes when resources are limited, as described in a training program.','The author believes practice works best if learners are told what they did wrong.','The author suggests that practice and feedback are unrelated.','The author claims feedback is useful only when students stop practicing.','The author believes mistakes should be ignored during practice.','A','התשובה הנכונה שומרת על משמעות המשפט המקורי בלי להוסיף או לסתור מידע.','["simulation_1", "restatement", "practice_pool"]'::jsonb,70,'B2','approved',false);
